input.sparql:
PREFIX brick: <https://brickschema.org/schema/1.0.2/Brick#>
PREFIX ref: <https://brickschema.org/schema/1.0.2/BrickFrame#>
SELECT ?ts_id ?point WHERE {
 ?zone brick:hasLocation <https://example.com/Building/Third_Floor/DataCenter_zone/DataCenter_top_ZN_6> ;
		brick:hasPoint ?point .
 ?point ref:hasExternalReference ?ref .
 ?ref ref:hasTimeseriesId ?ts_id .
 FILTER(CONTAINS(str(?point), 'occupant_count'))
}
